sp_widget.client_script:
api.controller = function() {

    var c = this;


    c.processing = false;


    /* =========================================
       ACCEPT / REJECT REQUEST
       ========================================= */

    c.respond = function(
        request,
        decision
    ) {


        if (
            !request ||
            !request.sys_id
        ) {

            alert(
                'Unable to identify the team request.'
            );

            return;

        }


        if (c.processing) {
            return;
        }


        c.processing = true;


        c.server.get({

            action:
                'respond_to_request',

            requestId:
                request.sys_id,

            decision:
                decision

        }).then(function(response) {


            c.processing = false;


            var result =
                response.data || {};


            if (
                result.responseMessage
            ) {

                alert(
                    result.responseMessage
                );

            }


            /*
             * Reload the widget.
             *
             * Accepted / Rejected request
             * will no longer appear under
             * Pending Team Requests.
             */

            c.server.update();


        }, function(error) {


            c.processing = false;


            console.log(
                'REQUEST RESPONSE ERROR:',
                error
            );


            alert(
                'Unable to update the team request.'
            );


        });

    };

};

sp_widget.css:
/* =========================================================
   CAMPUS CONNECT - MY TEAM REQUESTS
   COMPLETE STANDALONE CSS
   ========================================================= */

.cc-team-requests-page {
    min-height: 100vh;
    padding: 32px 0 0 180px;
    background: transparent;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI",
                 Roboto, Arial, sans-serif;
    box-sizing: border-box;
}

.cc-team-requests-page *,
.cc-team-requests-page *::before,
.cc-team-requests-page *::after {
    box-sizing: border-box;
}


/* =========================================================
   HERO
   ========================================================= */

.cc-team-requests-hero {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto 28px;
    padding: 30px 34px;
    border-radius: 18px;
    background: linear-gradient(
        135deg,
        #173f73 0%,
        #1f5d9b 55%,
        #2877b9 100%
    );
    display: flex;
    align-items: center;
    gap: 22px;
    box-shadow: 0 12px 30px rgba(23, 63, 115, 0.16);
}

.cc-team-requests-hero .cc-hero-icon {
    width: 62px;
    height: 62px;
    min-width: 62px;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.16);
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 28px;
}

.cc-team-requests-hero .cc-hero-content h1 {
    margin: 0;
    color: #ffffff;
    font-size: 30px;
    line-height: 1.2;
    font-weight: 700;
}

.cc-team-requests-hero .cc-hero-content p {
    margin: 8px 0 0;
    color: rgba(255, 255, 255, 0.84);
    font-size: 15px;
    line-height: 1.5;
}

.cc-hero-eyebrow {
    margin-bottom: 5px;
    color: rgba(255, 255, 255, 0.72);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.3px;
}


/* =========================================================
   REQUEST SECTION
   ========================================================= */

.cc-requests-section {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto;
}

.cc-section-header {
    margin-bottom: 18px;
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 20px;
}

.cc-section-eyebrow {
    margin-bottom: 5px;
    color: #1f5d9b;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1px;
}

.cc-section-header h2 {
    margin: 0;
    color: #1f2937;
    font-size: 22px;
    font-weight: 700;
}

.cc-section-header p {
    margin: 5px 0 0;
    color: #7b8794;
    font-size: 14px;
}

.cc-request-count {
    padding: 7px 14px;
    border-radius: 20px;
    background: #edf5ff;
    color: #1f5d9b;
    font-size: 13px;
    font-weight: 700;
    white-space: nowrap;
}


/* =========================================================
   REQUEST LIST
   ========================================================= */

.cc-team-request-list {
    display: flex;
    flex-direction: column;
    gap: 18px;
}


/* =========================================================
   REQUEST CARD
   ========================================================= */

.cc-team-request-card {
    overflow: hidden;
    background: #ffffff;
    border: 1px solid #e3e8ef;
    border-radius: 16px;
    box-shadow: 0 6px 20px rgba(31, 45, 61, 0.07);
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.cc-team-request-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 27px rgba(31, 45, 61, 0.10);
}


/* =========================================================
   REQUEST HEADER
   ========================================================= */

.cc-request-card-header {
    padding: 21px 23px;
    border-bottom: 1px solid #edf0f4;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
}

.cc-request-student {
    display: flex;
    align-items: center;
    gap: 14px;
}

.cc-student-avatar {
    width: 50px;
    height: 50px;
    min-width: 50px;
    border-radius: 50%;
    background: #eaf3fc;
    color: #1f5d9b;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 19px;
    font-weight: 700;
}

.cc-student-details h3 {
    margin: 0 0 6px;
    color: #243b53;
    font-size: 17px;
    font-weight: 700;
}

.cc-pending-badge {
    display: inline-flex;
    align-items: center;
    padding: 5px 9px;
    border-radius: 15px;
    background: #fff7e6;
    color: #9a6700;
    font-size: 11px;
    font-weight: 700;
}

.cc-request-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;
    border-radius: 11px;
    background: #f0f5fb;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
}


/* =========================================================
   REQUEST BODY
   ========================================================= */

.cc-request-card-body {
    padding: 23px;
}


/* =========================================================
   INFORMATION GRID
   ========================================================= */

.cc-info-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
}

.cc-info-block {
    min-width: 0;
    padding: 15px 16px;
    border: 1px solid #e8edf3;
    border-radius: 11px;
    background: #fafbfd;
}

.cc-info-label {
    margin-bottom: 7px;
    color: #7b8794;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.8px;
}

.cc-info-value {
    color: #26384a;
    font-size: 14px;
    font-weight: 600;
    line-height: 1.5;
    word-break: break-word;
}


/* =========================================================
   REQUEST ACTIONS
   ========================================================= */

.cc-request-actions {
    margin-top: 22px;
    padding-top: 20px;
    border-top: 1px solid #edf0f4;
    display: flex;
    justify-content: flex-end;
    gap: 11px;
}

.cc-accept-btn,
.cc-reject-btn {
    min-height: 43px;
    padding: 0 18px;
    border-radius: 9px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition:
        background 0.2s ease,
        border-color 0.2s ease,
        color 0.2s ease,
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.cc-accept-btn {
    border: 1px solid #1d8755;
    background: #1d8755;
    color: #ffffff;
}

.cc-accept-btn:hover:not(:disabled) {
    background: #176d45;
    border-color: #176d45;
    transform: translateY(-1px);
    box-shadow: 0 5px 14px rgba(29, 135, 85, 0.20);
}

.cc-reject-btn {
    border: 1px solid #d9534f;
    background: #ffffff;
    color: #c43d39;
}

.cc-reject-btn:hover:not(:disabled) {
    background: #fff4f3;
    border-color: #c43d39;
    transform: translateY(-1px);
}

.cc-accept-btn:disabled,
.cc-reject-btn:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.cc-no-requests-card {
    width: 100%;
    max-width: 1180px;
    margin: 0 auto;
    padding: 62px 30px;
    text-align: center;
    background: #ffffff;
    border: 1px solid #e3e8ef;
    border-radius: 16px;
    box-shadow: 0 6px 20px rgba(31, 45, 61, 0.06);
}

.cc-empty-icon {
    width: 64px;
    height: 64px;
    margin: 0 auto 17px;
    border-radius: 50%;
    background: #edf8f2;
    color: #218653;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 27px;
    font-weight: 700;
}

.cc-no-requests-card h3 {
    margin: 0;
    color: #344054;
    font-size: 20px;
    font-weight: 700;
}

.cc-no-requests-card p {
    max-width: 510px;
    margin: 9px auto 0;
    color: #7b8794;
    font-size: 14px;
    line-height: 1.6;
}


/* =========================================================
   RESPONSIVE - TABLET
   ========================================================= */

@media (max-width: 768px) {

    .cc-team-requests-page {
        padding: 18px;
    }

    .cc-team-requests-hero {
        padding: 24px;
        gap: 15px;
    }

    .cc-team-requests-hero .cc-hero-icon {
        width: 50px;
        height: 50px;
        min-width: 50px;
        font-size: 23px;
    }

    .cc-team-requests-hero .cc-hero-content h1 {
        font-size: 24px;
    }

    .cc-section-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .cc-info-grid {
        grid-template-columns: 1fr;
    }

    .cc-request-card-header {
        align-items: flex-start;
    }

}


/* =========================================================
   RESPONSIVE - MOBILE
   ========================================================= */

@media (max-width: 480px) {

    .cc-team-requests-page {
        padding: 12px;
    }

    .cc-team-requests-hero {
        padding: 20px;
        border-radius: 14px;
    }

    .cc-team-requests-hero .cc-hero-content h1 {
        font-size: 21px;
    }

    .cc-team-requests-hero .cc-hero-content p {
        font-size: 13px;
    }

    .cc-request-card-header {
        padding: 17px;
    }

    .cc-request-card-body {
        padding: 17px;
    }

    .cc-request-icon {
        display: none;
    }

    .cc-request-actions {
        flex-direction: column;
    }

    .cc-accept-btn,
    .cc-reject-btn {
        width: 100%;
    }

    .cc-no-requests-card {
        padding: 45px 20px;
    }

}

sp_widget.script:
(function() {

    data.requests = [];
    data.sentRequests = [];
    data.responseMessage = '';

    var currentUser = gs.getUserID();

    if (!currentUser) {
        return;
    }


    /* =========================================
       ACCEPT / REJECT REQUEST
       ========================================= */

    if (
        input &&
        input.action == 'respond_to_request'
    ) {

        var requestId =
            String(input.requestId || '');

        var decision =
            String(input.decision || '').toLowerCase();


        if (!requestId) {

            data.responseMessage =
                'Team request information is missing.';

            return;
        }


        if (
            decision != 'accepted' &&
            decision != 'rejected'
        ) {

            data.responseMessage =
                'Invalid request decision.';

            return;
        }


        /* =====================================
           GET TEAM MEMBER REQUEST
           ===================================== */

        var member =
            new GlideRecord(
                'x_snc_campus_con_0_team_members'
            );


        if (!member.get(requestId)) {

            data.responseMessage =
                'The team request was not found.';

            return;
        }


        /* =====================================
           GET TEAM
           ===================================== */

        var requestTeam =
            new GlideRecord(
                'x_snc_campus_con_0_teams'
            );


        if (
            !requestTeam.get(
                member.getValue('team')
            )
        ) {

            data.responseMessage =
                'The associated team was not found.';

            return;
        }


        /* =====================================
           SECURITY CHECK
           ===================================== */

        /*
         * The Team Member student is the RECEIVER.
         *
         * Example:
         * Sruthi sends request to Hema
         *
         * member.student = Hema
         * currentUser    = Hema
         *
         * Therefore Hema is authorized to respond.
         */

        if (
            member.getValue('student') != currentUser
        ) {

            data.responseMessage =
                'You are not authorized to respond to this request.';

            return;
        }


        /* =====================================
           REQUEST MUST BE PENDING
           ===================================== */

        if (
            member.getValue('join_status') != 'requested'
        ) {

            data.responseMessage =
                'This team request has already been processed.';

            return;
        }


        /* =====================================
           ACCEPT
           ===================================== */

        if (
            decision == 'accepted'
        ) {

            var acceptedMembers =
                new GlideRecord(
                    'x_snc_campus_con_0_team_members'
                );


            acceptedMembers.addQuery(
                'team',
                requestTeam.getUniqueValue()
            );


            acceptedMembers.addQuery(
                'join_status',
                'accepted'
            );


            acceptedMembers.query();


            var acceptedCount = 0;


            while (
                acceptedMembers.next()
            ) {

                acceptedCount++;

            }


            /*
             * Maximum team size = 5
             */

            if (
                acceptedCount >= 5
            ) {

                data.responseMessage =
                    'This team already has the maximum number of members.';

                return;
            }


            /* =================================
               ACCEPT MEMBER
               ================================= */

            member.setValue(
                'join_status',
                'accepted'
            );


            member.setValue(
                'commitment_confirmed',
                true
            );


            var acceptedId =
                member.update();


            if (!acceptedId) {

                data.responseMessage =
                    'Unable to accept the team request.';

                return;
            }


            /* =================================
               CHECK FINAL TEAM SIZE
               ================================= */

            var finalAccepted =
                new GlideRecord(
                    'x_snc_campus_con_0_team_members'
                );


            finalAccepted.addQuery(
                'team',
                requestTeam.getUniqueValue()
            );


            finalAccepted.addQuery(
                'join_status',
                'accepted'
            );


            finalAccepted.query();


            var finalCount = 0;


            while (
                finalAccepted.next()
            ) {

                finalCount++;

            }


            if (
                finalCount >= 5
            ) {

                requestTeam.setValue(
                    'status',
                    'closed'
                );


                requestTeam.update();

            }


            data.responseMessage =
                'Team request accepted successfully.';

            return;
        }


        /* =========================================
           REJECT
           ========================================= */

        if (
            decision == 'rejected'
        ) {

            member.setValue(
                'join_status',
                'rejected'
            );


            member.setValue(
                'commitment_confirmed',
                true
            );


            var rejectedId =
                member.update();


            if (!rejectedId) {

                data.responseMessage =
                    'Unable to reject the team request.';

                return;
            }


            data.responseMessage =
                'Team request rejected.';

            return;
        }

    }


    /* =========================================
       INCOMING TEAM REQUESTS
       ========================================= */

    var incomingMember =
        new GlideRecord(
            'x_snc_campus_con_0_team_members'
        );


    /*
     * Logged-in student is the RECEIVER.
     *
     * Example:
     * Sruthi → Hema
     *
     * incomingMember.student = Hema
     */

    incomingMember.addQuery(
        'student',
        currentUser
    );


    incomingMember.addQuery(
        'join_status',
        'requested'
    );


    incomingMember.orderByDesc(
        'sys_created_on'
    );


    incomingMember.query();


    while (
        incomingMember.next()
    ) {

        var request = {};


        request.sys_id =
            incomingMember.getUniqueValue();


        /* =====================================
           GET TEAM
           ===================================== */

        var team =
            new GlideRecord(
                'x_snc_campus_con_0_teams'
            );


        var teamId =
            incomingMember.getValue('team');


        var requesterUserId = '';


        if (
            teamId &&
            team.get(teamId)
        ) {

            request.teamName =
                team.getValue(
                    'team_name'
                ) ||
                team.getDisplayValue(
                    'team_name'
                );


            request.eventName =
                team.getDisplayValue(
                    'event'
                );


            /* =================================
               IMPORTANT:
               TEAM LEAD = REQUESTER
               ================================= */

            requesterUserId =
                team.getValue(
                    'team_lead'
                );


        } else {

            request.teamName = '';
            request.eventName = '';

        }


        /* =====================================
           REQUESTER DETAILS
           ===================================== */

        /*
         * Do NOT use:
         *
         * incomingMember.student
         *
         * because that is the RECEIVER.
         *
         * We use team.team_lead because the
         * Team Lead is the person who created
         * the team and sent the request.
         */

        request.studentName = '';


        if (
            requesterUserId
        ) {

            var requesterUser =
                new GlideRecord('sys_user');


            if (
                requesterUser.get(
                    requesterUserId
                )
            ) {

                request.studentName =
                    requesterUser.getDisplayValue(
                        'name'
                    );

            }

        }


        request.status =
            incomingMember.getDisplayValue(
                'join_status'
            );


        /* =====================================
           GET REQUESTER STUDENT PROFILE
           ===================================== */

        request.collegeName = '';
        request.skills = '';
        request.location = '';


        var requesterProfile =
            new GlideRecord(
                'x_snc_campus_con_0_student_profile'
            );


        requesterProfile.addQuery(
            'student',
            requesterUserId
        );


        requesterProfile.setLimit(1);

        requesterProfile.query();


        if (
            requesterProfile.next()
        ) {

            request.collegeName =
                requesterProfile.getValue(
                    'college_name'
                ) || '';


            request.skills =
                requesterProfile.getValue(
                    'skills'
                ) || '';


            request.location =
                requesterProfile.getValue(
                    'location'
                ) || '';

        }


        /* =====================================
           ADD REQUEST
           ===================================== */

        data.requests.push(
            request
        );

    }


})();
